#!/bin/bash
# clean-cache.sh — Reclaim disk space taken by build caches.
#
# Deletes (all gitignored, all fully regenerated by the next build):
#   <build-dir>/go-cache                        Go build cache (GOCACHE for every CMake Go target)
#   <build-dir>/go-tmp                          GOTMPDIR scratch space
#   render/vulkan/crates/lurpic_render/target   Rust build directory
#
# Deliberately left untouched: binaries in <build-dir> (lurpic, lurpiclint),
# the runtime/drive evidence directories, and CMake's own configuration.
#
# Flags:
#   --dry-run        Print sizes and what would be deleted; delete nothing.
#   --build-dir DIR  CMake build directory (default: <repo>/build)
#   --go-only        Restrict the clean to the Go caches.
#   --rust-only      Restrict the clean to the Rust target directory.

set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
REPO_ROOT="$(cd "$SCRIPT_DIR/.." && pwd)"

BUILD_DIR="${REPO_ROOT}/build"
DRY_RUN=false
GO_ONLY=false
RUST_ONLY=false

while [[ $# -gt 0 ]]; do
    case "$1" in
        --dry-run) DRY_RUN=true; shift ;;
        --build-dir) BUILD_DIR="$2"; shift 2 ;;
        --go-only) GO_ONLY=true; shift ;;
        --rust-only) RUST_ONLY=true; shift ;;
        *) echo "unknown flag: $1"; exit 1 ;;
    esac
done

if [[ "$GO_ONLY" == true && "$RUST_ONLY" == true ]]; then
    echo "--go-only and --rust-only are mutually exclusive"; exit 1
fi

if [[ "$BUILD_DIR" != /* ]]; then
    BUILD_DIR="$(cd "$BUILD_DIR" && pwd)"
fi

GO_CACHE_DIR="${BUILD_DIR}/go-cache"
GO_TMP_DIR="${BUILD_DIR}/go-tmp"
RUST_TARGET_DIR="${REPO_ROOT}/render/vulkan/crates/lurpic_render/target"

print_size() {
    local label="$1" path="$2"
    if [[ -d "$path" ]]; then
        printf '  %-12s %s\n' "$(du -sh "$path" 2>/dev/null | cut -f1)" "$path"
    else
        printf '  %-12s %s\n' "(absent)" "$path"
    fi
}

remove_dir_contents() {
    local path="$1"
    if [[ "$DRY_RUN" == true ]]; then
        return
    fi
    if [[ -d "$path" ]]; then
        find "$path" -mindepth 1 -maxdepth 1 -exec rm -rf {} +
    fi
}

CLEAN_GO=true
CLEAN_RUST=true
if [[ "$GO_ONLY" == true ]]; then
    CLEAN_RUST=false
elif [[ "$RUST_ONLY" == true ]]; then
    CLEAN_GO=false
fi

echo "lurpicUI build caches:"
print_size "go-cache" "$GO_CACHE_DIR"
print_size "go-tmp" "$GO_TMP_DIR"
print_size "rust-target" "$RUST_TARGET_DIR"

if [[ "$DRY_RUN" == true ]]; then
    echo "dry run: nothing was deleted (drop --dry-run to clean)"
    exit 0
fi

if [[ "$CLEAN_GO" == true ]]; then
    remove_dir_contents "$GO_TMP_DIR"
    mkdir -p "$GO_CACHE_DIR"
    if command -v go >/dev/null 2>&1; then
        # `go clean -cache` understands the cache layout; deleting entries out
        # from under a concurrent Go build is still safe (Go recompiles on a
        # cache miss), but a racing build may be slower.
        GOCACHE="$GO_CACHE_DIR" go clean -cache -testcache
    else
        remove_dir_contents "$GO_CACHE_DIR"
    fi
    echo "Go caches cleaned: $GO_CACHE_DIR"
fi

if [[ "$CLEAN_RUST" == true ]]; then
    if [[ -d "$RUST_TARGET_DIR" ]]; then
        if command -v cargo >/dev/null 2>&1; then
            cargo clean --manifest-path "${REPO_ROOT}/render/vulkan/crates/lurpic_render/Cargo.toml"
        else
            rm -rf "$RUST_TARGET_DIR"
        fi
        echo "Rust target cleaned: $RUST_TARGET_DIR"
    else
        echo "Rust target already absent: $RUST_TARGET_DIR"
    fi
fi

echo "remaining cache sizes:"
print_size "go-cache" "$GO_CACHE_DIR"
print_size "go-tmp" "$GO_TMP_DIR"
print_size "rust-target" "$RUST_TARGET_DIR"
